const N = 1000;

// --- naive cache-aside: every concurrent miss calls origin ---
let naiveOrigin = 0;
function naiveOriginCall() { naiveOrigin++; return 'value'; }
for (let i = 0; i < N; i++) {
  // cache empty (expired) for the whole window, nobody coordinates
  naiveOriginCall();
}

// --- single-flight: one in-flight recompute shared by all callers ---
let sfOrigin = 0;
const inFlight = new Map();
function singleFlight(key, fn) {
  if (inFlight.has(key)) return inFlight.get(key);
  const p = fn();
  inFlight.set(key, p);
  return p;
}
function sfOriginCall() { sfOrigin++; return 'value'; }
for (let i = 0; i < N; i++) {
  singleFlight('feed', sfOriginCall);
}

console.log('naive=' + naiveOrigin + ' singleflight=' + sfOrigin);
